//   sin 由 cos[(k+1536) & 2047] 读出: cos(t - pi/2) = sin(t), 数值与
//   原 {cos,sin} 表逐位相同 (fft4096 在 ph1 换地址, ph3 收 sin)
module twiddle_rom (
    input             I_clk  ,
    input      [10:0] I_addr ,
    output reg [15:0] O_cos
);
    reg [15:0] rom [0:2047];
    initial begin
        rom[   0] = 16'h7FFF;   // cos= 32767
        rom[   1] = 16'h7FFF;   // cos= 32767
        rom[   2] = 16'h7FFF;   // cos= 32767
        rom[   3] = 16'h7FFF;   // cos= 32767
        rom[   4] = 16'h7FFE;   // cos= 32766
        rom[   5] = 16'h7FFE;   // cos= 32766
        rom[   6] = 16'h7FFE;   // cos= 32766
        rom[   7] = 16'h7FFD;   // cos= 32765
        rom[   8] = 16'h7FFD;   // cos= 32765
        rom[   9] = 16'h7FFC;   // cos= 32764
        rom[  10] = 16'h7FFB;   // cos= 32763
        rom[  11] = 16'h7FFA;   // cos= 32762
        rom[  12] = 16'h7FF9;   // cos= 32761
        rom[  13] = 16'h7FF8;   // cos= 32760
        rom[  14] = 16'h7FF7;   // cos= 32759
        rom[  15] = 16'h7FF6;   // cos= 32758
        rom[  16] = 16'h7FF5;   // cos= 32757
        rom[  17] = 16'h7FF4;   // cos= 32756
        rom[  18] = 16'h7FF3;   // cos= 32755
        rom[  19] = 16'h7FF1;   // cos= 32753
        rom[  20] = 16'h7FF0;   // cos= 32752
        rom[  21] = 16'h7FEE;   // cos= 32750
        rom[  22] = 16'h7FEC;   // cos= 32748
        rom[  23] = 16'h7FEB;   // cos= 32747
        rom[  24] = 16'h7FE9;   // cos= 32745
        rom[  25] = 16'h7FE7;   // cos= 32743
        rom[  26] = 16'h7FE5;   // cos= 32741
        rom[  27] = 16'h7FE3;   // cos= 32739
        rom[  28] = 16'h7FE1;   // cos= 32737
        rom[  29] = 16'h7FDF;   // cos= 32735
        rom[  30] = 16'h7FDC;   // cos= 32732
